package com.movis.warehouse;

import android.app.*;
import android.os.*;
import android.content.Intent;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.InputType;
import android.util.Base64;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Staff companion: new in-app images, server checked totals, no direct balance editing. */
public class RiceActivity extends Activity {
    private static final String SERVER="https://movis-1fxf.onrender.com";
    private static final int INK=0xff172b39, TEAL=0xff087f72, PAPER=0xfff3f6f8;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final HashMap<String,String> keys=new HashMap<>();
    private final ArrayList<Button> buttons=new ArrayList<>();
    private LinearLayout root,body;
    private TextView status;
    private String token="",username="",role="",page="Inventory",actionId="";
    private JSONObject state=new JSONObject(),action=new JSONObject(),pendingImage;
    private boolean busy=false;
    interface Work { JSONObject run() throws Exception; }
    interface Reply { void done(JSONObject r) throws Exception; }
    @Override public void onCreate(Bundle saved){super.onCreate(saved);login();}
    @Override protected void onDestroy(){super.onDestroy();worker.shutdownNow();}
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    JSONObject obj(Object... parts){JSONObject r=new JSONObject();try{for(int i=0;i<parts.length;i+=2)r.put((String)parts[i],parts[i+1]);}catch(JSONException e){throw new IllegalArgumentException(e);}return r;}
    JSONArray arr(JSONObject o,String key){JSONArray a=o.optJSONArray(key);return a==null?new JSONArray():a;}
    LinearLayout col(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
    TextView txt(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(INK);t.setTextSize(size);t.setPadding(0,dp(8),0,dp(8));return t;}
    void heading(LinearLayout p,String s){TextView t=txt(s,23);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);p.addView(t);}
    GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));return d;}
    LinearLayout card(LinearLayout parent){LinearLayout c=col();c.setPadding(dp(16),dp(12),dp(16),dp(12));c.setBackground(bg(Color.WHITE));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);parent.addView(c,lp);return c;}
    Button button(LinearLayout p,String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEAL);p.addView(b);buttons.add(b);b.setEnabled(!busy);b.setOnClickListener(v->{if(!busy)try{action.run();}catch(Exception e){error(e.getMessage());}});return b;}
    EditText field(LinearLayout p,String label,boolean number){p.addView(txt(label,14));EditText e=new EditText(this);e.setSingleLine();e.setInputType(number?InputType.TYPE_CLASS_NUMBER:InputType.TYPE_CLASS_TEXT);p.addView(e);return e;}
    CheckBox check(LinearLayout p,String s,boolean checked){CheckBox c=new CheckBox(this);c.setText(s);c.setTextColor(INK);c.setChecked(checked);p.addView(c);return c;}
    void error(String s){status.setText(s==null?"Request failed":s);status.setTextColor(0xffa44131);}
    void shell(String title){buttons.clear();root=col();root.setBackgroundColor(PAPER);root.setPadding(dp(16),dp(8),dp(16),dp(8));root.setOnApplyWindowInsetsListener((v,in)->{if(Build.VERSION.SDK_INT>=30){Insets bars=in.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());Insets ime=in.getInsets(WindowInsets.Type.ime());v.setPadding(dp(16)+bars.left,dp(8)+bars.top,dp(16)+bars.right,dp(8)+Math.max(bars.bottom,ime.bottom));}else v.setPadding(dp(16)+in.getSystemWindowInsetLeft(),dp(8)+in.getSystemWindowInsetTop(),dp(16)+in.getSystemWindowInsetRight(),dp(8)+in.getSystemWindowInsetBottom());return in;});getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);heading(root,"MOVIS  |  "+title);status=txt("",14);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);ScrollView scroll=new ScrollView(this);body=col();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();}
    void task(Work work,Reply reply){if(busy)return;busy=true;for(Button b:buttons)b.setEnabled(false);status.setText("Connecting to MOVIS...");status.setTextColor(TEAL);worker.execute(()->{try{JSONObject r=work.run();runOnUiThread(()->{busy=false;for(Button b:buttons)b.setEnabled(true);status.setText("");try{reply.done(r);}catch(Exception e){error(e.getMessage());}});}catch(Exception e){runOnUiThread(()->{busy=false;for(Button b:buttons)b.setEnabled(true);if(e instanceof ApiError&&((ApiError)e).code==401){token="";login();}error(e.getMessage());});}});}
    static class ApiError extends IOException{int code;ApiError(int code,String s){super(s);this.code=code;}}
    JSONObject api(String path,JSONObject data)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(SERVER+path).openConnection();c.setConnectTimeout(90000);c.setReadTimeout(120000);c.setRequestProperty("Authorization","Bearer "+token);try{if(data!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(data.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();InputStream stream=code<400?c.getInputStream():c.getErrorStream();if(stream==null)throw new IOException("No server response");String text;try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);text=out.toString("UTF-8");}JSONObject r;try{r=new JSONObject(text);}catch(JSONException e){throw new IOException("Invalid server response. The updated backend must be deployed first.");}if(code>=400)throw new ApiError(code,r.optString("error","Request failed"));return r;}catch(SocketTimeoutException e){throw new IOException("Connection interrupted. Refresh before retrying. The same unchanged submission uses its original request ID.");}finally{c.disconnect();}}
    JSONObject request(String kind,JSONObject d){String sig=kind+d.toString();String key=keys.get(sig);if(key==null){key=UUID.randomUUID().toString();keys.put(sig,key);}try{d.put("request_id",key);}catch(JSONException ignored){}return d;}
    void login(){shell("Elder Jay rice mill");heading(body,"Staff sign in");body.addView(txt("Record rice transactions using new camera images. Internet is required.",15));LinearLayout f=card(body);EditText u=field(f,"Username",false),p=field(f,"Password",false);p.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);u.setText(getPreferences(MODE_PRIVATE).getString("username",""));button(f,"Sign in",()->task(()->api("/login",obj("username",u.getText().toString().trim(),"password",p.getText().toString())),r->{token=r.getString("token");username=r.getString("username");role=r.getString("role");getPreferences(MODE_PRIVATE).edit().putString("username",username).apply();load();}));}
    void load(){task(()->api("/v2/state",null),r->{state=r;home(page);});}
    String name(int id){JSONArray p=arr(state,"products");for(int i=0;i<p.length();i++)if(p.optJSONObject(i).optInt("id")==id)return p.optJSONObject(i).optString("name");return "Rice "+id;}
    boolean write(){return role.equals("operator")||role.equals("admin");}
    void home(String tab){page=tab;shell(username);LinearLayout nav=new LinearLayout(this);root.addView(nav);for(String n:new String[]{"Inventory","Actions","Returns","Recent"}){Button nb=button(nav,n,()->{page=n;load();});nb.setTextSize(11);nb.setMinWidth(0);nb.setMinimumWidth(0);nb.setPadding(0,0,0,0);nb.setLayoutParams(new LinearLayout.LayoutParams(0,dp(54),1));}if(state.optString("mode").equals("demo"))body.addView(txt("DEMO: scanner results are synthetic until a trained YOLO26 model is connected.",14));button(body,"Refresh",()->load());button(body,"Sign out",()->task(()->api("/logout",obj()),r->{token="";actionId="";pendingImage=null;keys.clear();login();}));
        if(tab.equals("Inventory")){heading(body,"Rice inventory");for(int i=0;i<arr(state,"products").length();i++){JSONObject p=arr(state,"products").optJSONObject(i);LinearLayout c=card(body);heading(c,p.optString("name"));c.addView(txt(p.optInt("quantity")+" available sacks  |  25 kg each\n"+p.optString("sku"),17));}}
        else if(tab.equals("Actions")){heading(body,"Choose a transaction");if(write())for(String k:new String[]{"stock-in","stock-out","count","return","damage"})button(body,k.equals("count")?"Inventory Count":k,()->start(k));body.addView(txt("Choose the action before capture. Saved scans do not change stock.",14));JSONArray acts=arr(state,"actions");for(int i=0;i<acts.length();i++){JSONObject a=acts.optJSONObject(i);LinearLayout c=card(body);heading(c,a.optString("kind"));c.addView(txt(a.optString("state")+"  |  "+a.optString("created_at"),14));button(c,a.optString("state").equals("open")?"Continue action":"View saved action",()->open(a.optString("id")));}}
        else if(tab.equals("Returns")){heading(body,"Returns and damage");body.addView(txt("The owner inspects and approves final decisions in the administrator website. Pending records leave stock unchanged.",15));JSONArray cases=arr(state,"cases");for(int i=0;i<cases.length();i++){JSONObject r=cases.optJSONObject(i);LinearLayout c=card(body);heading(c,r.optString("name"));c.addView(txt(r.optString("kind")+"  |  "+r.optInt("quantity")+" sacks\n"+r.optString("status")+"  |  "+r.optInt("remaining")+" awaiting decision\n"+r.optString("condition")+"\n"+r.optString("reason"),14));}}
        else{heading(body,"Your recent stock transactions");JSONArray h=arr(state,"history");for(int i=0;i<h.length();i++){JSONObject r=h.optJSONObject(i);LinearLayout c=card(body);heading(c,r.optString("name"));c.addView(txt(r.optString("kind")+"  |  "+r.optInt("difference")+" sacks\nPrevious "+r.optInt("previous_quantity")+"  ->  "+r.optInt("quantity")+"\n"+r.optString("username")+"  |  "+r.optString("created_at")+"\n"+r.optString("reason"),14));}}
    }
    void start(String kind){LinearLayout f=col();f.setPadding(dp(18),dp(8),dp(18),dp(8));f.addView(txt("Select the rice products included in this action.",15));ArrayList<CheckBox> picks=new ArrayList<>();JSONArray ps=arr(state,"products");for(int i=0;i<ps.length();i++)picks.add(check(f,ps.optJSONObject(i).optString("name"),true));AlertDialog d=new AlertDialog.Builder(this).setTitle(kind.equals("count")?"Start inventory count":kind).setView(f).setNegativeButton("Cancel",null).setPositiveButton("Start",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{JSONArray ids=new JSONArray();for(int i=0;i<picks.size();i++)if(picks.get(i).isChecked())ids.put(ps.optJSONObject(i).optInt("id"));if(ids.length()==0){error("Choose at least one rice product");return;}d.dismiss();task(()->api("/v2/open",request("open",obj("kind",kind,"products",ids))),r->{keys.entrySet().removeIf(e->e.getKey().startsWith("open"));open(r.optString("action_id"));});}));d.show();}
    void open(String id){actionId=id;task(()->api("/v2/state?action_id="+URLEncoder.encode(id,"UTF-8")+"&images=1",null),r->{action=r.getJSONObject("action");actionScreen();});}
    JSONObject base(){return obj("action_id",actionId,"revision",action.optInt("revision"));}
    void actionScreen(){shell(action.optString("kind"));button(body,"Back to actions",()->{page="Actions";load();});boolean editable=action.optString("state").equals("open");body.addView(txt("Action: "+action.optString("state")+"\nEach sack must appear only once. Hidden sacks need another image or a separate checked entry with a reason.",14));
        if(pendingImage!=null&&pendingImage.optString("action_id").equals(actionId)&&editable)button(body,"Retry pending image scan",()->sendImage());
        JSONArray images=arr(action,"images");HashMap<Integer,Integer> totals=new HashMap<>();LinearLayout cameraRow=new LinearLayout(this);body.addView(cameraRow);if(editable)button(cameraRow,"Add more images",()->{if(pendingImage!=null){error("Retry the pending image or start another action first");return;}startActivityForResult(new Intent(this,CameraActivity.class),101);});LinearLayout gallery=col();cameraRow.addView(gallery,new LinearLayout.LayoutParams(0,-2,1));gallery.addView(txt("Captured Images",16));int kept=0;
        for(int i=0;i<images.length();i++){JSONObject im=images.optJSONObject(i);if(im.optInt("deleted")==1)continue;kept++;byte[] bytes=Base64.decode(im.optString("image"),Base64.DEFAULT);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=4;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);LinearLayout c=card(gallery);if(bitmap!=null){ImageView preview=new ImageView(this);preview.setImageBitmap(bitmap);preview.setAdjustViewBounds(true);preview.setContentDescription("Enlarge captured image "+kept);c.addView(preview,new LinearLayout.LayoutParams(-1,dp(110)));preview.setOnClickListener(v->enlarge(im));}c.addView(txt((im.optInt("reviewed")==1?"Checked":"Needs checking")+"  |  "+im.optString("processing_ms")+" ms",13));if(editable){button(c,"Check quantities",()->review(im));button(c,"Delete / retake",()->{JSONObject d=base();try{d.put("image_id",im.optString("id"));}catch(JSONException ignored){}task(()->api("/v2/delete",request("delete",d)),r->{pendingImage=null;open(actionId);});});}JSONArray lines=arr(im,"checked");if(im.optInt("reviewed")==1)for(int j=0;j<lines.length();j++){JSONObject l=lines.optJSONObject(j);int pid=l.optInt("product_id");totals.put(pid,totals.getOrDefault(pid,0)+l.optInt("quantity"));}}
        if(kept==0)gallery.addView(txt("New images for this action appear here.",14));heading(body,"Checked totals from kept images");JSONArray snapshot=arr(action,"snapshot");for(int i=0;i<snapshot.length();i++){int pid=snapshot.optJSONObject(i).optInt("product_id");body.addView(txt(name(pid)+": "+totals.getOrDefault(pid,0)+" sacks",16));}
        if(editable){button(body,"Refresh action",()->open(actionId));if(action.optString("kind").equals("count"))button(body,"Review changed stock baseline",()->new AlertDialog.Builder(this).setTitle("Recheck affected sacks").setMessage("This reads current stock and resets image verification. Physically recheck the affected sacks and check every retained image again before finishing.").setNegativeButton("Cancel",null).setPositiveButton("I rechecked affected sacks",(d,w)->{JSONObject p=base();try{p.put("confirmed_review",true);}catch(JSONException ignored){}task(()->api("/v2/refresh-count",request("refresh-count",p)),r->open(actionId));}).show());button(body,action.optString("kind").equals("count")?"Finish count":"Submit transaction",()->completeDialog());}
        else if(action.optString("kind").equals("count")){JSONArray comp=arr(action,"comparison");for(int i=0;i<comp.length();i++){JSONObject r=comp.optJSONObject(i);body.addView(txt(name(r.optInt("product_id"))+"  |  recorded "+r.optInt("quantity")+"  |  count "+r.optInt("count")+"  |  difference "+r.optInt("difference")+(r.optBoolean("adjusted")?"  |  corrected":""),15));}if(state.optJSONObject("user").optBoolean("can_adjust"))button(body,"Confirm adjustment",()->adjust());else body.addView(txt("Saved count leaves stock unchanged. An authorized user must confirm any correction.",14));}
    }
    void enlarge(JSONObject im){byte[] bytes=Base64.decode(im.optString("image"),Base64.DEFAULT);Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(b==null)return;ScrollView scroll=new ScrollView(this);LinearLayout f=col();scroll.addView(f);f.addView(new Boxes(b,arr(im,"raw")),new LinearLayout.LayoutParams(-1,dp(400)));f.addView(txt("Original "+im.optString("model_version")+" results; user corrections are stored separately.",14));for(int i=0;i<arr(im,"raw").length();i++){JSONObject r=arr(im,"raw").optJSONObject(i);f.addView(txt(r.optString("name")+"  |  "+Math.round(r.optDouble("confidence")*100)+"%",14));}new AlertDialog.Builder(this).setTitle("Captured image").setView(scroll).setPositiveButton("Close",null).show();}
    void review(JSONObject im){LinearLayout f=col();f.setPadding(dp(16),dp(8),dp(16),dp(8));JSONArray snap=arr(action,"snapshot");ArrayList<EditText> qs=new ArrayList<>();HashMap<Integer,Integer> raw=new HashMap<>();for(int i=0;i<arr(im,"raw").length();i++){int pid=arr(im,"raw").optJSONObject(i).optInt("product_id");raw.put(pid,raw.getOrDefault(pid,0)+1);}HashMap<Integer,Integer> checked=new HashMap<>();for(int i=0;i<arr(im,"checked").length();i++){JSONObject l=arr(im,"checked").optJSONObject(i);checked.put(l.optInt("product_id"),l.optInt("quantity"));}f.addView(txt("Correct each rice product count. Use zero for misidentified products and add the quantity under the correct rice name.",14));for(int i=0;i<snap.length();i++){int pid=snap.optJSONObject(i).optInt("product_id");EditText q=field(f,name(pid)+"  |  raw detected "+raw.getOrDefault(pid,0),true);q.setText(String.valueOf(checked.getOrDefault(pid,raw.getOrDefault(pid,0))));qs.add(q);}CheckBox confirmed=check(f,"I checked this image and corrected product names and quantities",false);TextView err=txt("",14);f.addView(err);AlertDialog d=new AlertDialog.Builder(this).setTitle("Check image quantities").setView(f).setNegativeButton("Cancel",null).setPositiveButton("Save scan",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{if(!confirmed.isChecked())throw new Exception("Confirm you checked the image");JSONArray lines=new JSONArray();for(int i=0;i<qs.size();i++){int qty=Integer.parseInt(qs.get(i).getText().toString());if(qty<0)throw new Exception("Use nonnegative whole sacks");lines.put(obj("product_id",snap.optJSONObject(i).optInt("product_id"),"quantity",qty));}JSONObject p=base();p.put("image_id",im.optString("id"));p.put("checked",lines);p.put("confirmed",true);d.dismiss();task(()->api("/v2/review",request("review",p)),r->open(actionId));}catch(Exception e){err.setText(e.getMessage());}}));d.show();}
    void completeDialog(){ScrollView scroll=new ScrollView(this);LinearLayout f=col();f.setPadding(dp(18),dp(8),dp(18),dp(8));scroll.addView(f);boolean count=action.optString("kind").equals("count"),ret=action.optString("kind").equals("return")||action.optString("kind").equals("damage");EditText reason=field(f,"Transaction / count reason",false);CheckBox unique=check(f,"Every sack is included only once across retained images and checked entries",false);JSONArray snap=arr(action,"snapshot");ArrayList<EditText> manual=new ArrayList<>(),why=new ArrayList<>();ArrayList<CheckBox> full=new ArrayList<>(),zero=new ArrayList<>();for(int i=0;i<snap.length();i++){int pid=snap.optJSONObject(i).optInt("product_id");heading(f,name(pid));EditText q=field(f,"Additional separately checked sacks (not in images)",true);q.setText("0");manual.add(q);why.add(field(f,"Reason for any additional checked quantity",false));if(count){full.add(check(f,"All sacks of this product were physically checked",false));zero.add(check(f,"If total is zero, I physically confirmed no sacks remain",false));}}CheckBox stocked=ret?check(f,"These sacks are already included in available stock",action.optString("kind").equals("damage")):null;EditText condition=ret?field(f,"Rice and packaging condition",false):null;TextView err=txt("",14);f.addView(err);AlertDialog d=new AlertDialog.Builder(this).setTitle(count?"Finish count - no stock change":"Review final transaction").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton(count?"Finish count":"Submit transaction",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{if(!unique.isChecked()||reason.getText().toString().trim().isEmpty())throw new Exception("Enter a reason and confirm sacks are counted once");JSONArray entries=new JSONArray();JSONObject fulls=new JSONObject(),zeros=new JSONObject();for(int i=0;i<snap.length();i++){int pid=snap.optJSONObject(i).optInt("product_id"),qty=Integer.parseInt(manual.get(i).getText().toString());if(qty<0)throw new Exception("Use nonnegative whole sacks");if(qty>0){if(why.get(i).getText().toString().trim().isEmpty())throw new Exception("Explain separately checked quantities");entries.put(obj("product_id",pid,"quantity",qty,"reason",why.get(i).getText().toString()));}if(count){if(!full.get(i).isChecked())throw new Exception("Confirm every chosen product was fully counted");fulls.put(String.valueOf(pid),full.get(i).isChecked());zeros.put(String.valueOf(pid),zero.get(i).isChecked());}}JSONObject p=base();p.put("reason",reason.getText().toString());p.put("unique_sacks",true);p.put("manual",entries);if(count){p.put("full_counts",fulls);p.put("zero_confirmed",zeros);}if(ret){p.put("already_stocked",stocked.isChecked());p.put("condition",condition.getText().toString());}String endpoint=count?"finish":"submit";JSONObject payload=request(endpoint,p);d.dismiss();task(()->api("/v2/"+endpoint,payload),r->{pendingImage=null;open(actionId);});}catch(Exception e){err.setText(e.getMessage());}}));d.show();}
    void adjust(){LinearLayout f=col();f.setPadding(dp(18),dp(8),dp(18),dp(8));JSONArray comp=arr(action,"comparison");ArrayList<Integer> ids=new ArrayList<>();ArrayList<CheckBox> picks=new ArrayList<>();for(int i=0;i<comp.length();i++){JSONObject r=comp.optJSONObject(i);if(r.optInt("difference")!=0&&!r.optBoolean("adjusted")){ids.add(r.optInt("product_id"));picks.add(check(f,name(r.optInt("product_id"))+": "+r.optInt("quantity")+"  ->  "+r.optInt("count"),true));}}EditText reason=field(f,"Stock correction reason",false);TextView err=txt("",14);f.addView(err);AlertDialog d=new AlertDialog.Builder(this).setTitle("Confirm separate adjustment").setView(f).setNegativeButton("Cancel",null).setPositiveButton("Confirm adjustment",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{JSONArray chosen=new JSONArray();for(int i=0;i<picks.size();i++)if(picks.get(i).isChecked())chosen.put(ids.get(i));if(chosen.length()==0||reason.getText().toString().trim().isEmpty())throw new Exception("Select a difference and enter a reason");JSONObject p=base();p.put("products",chosen);p.put("reason",reason.getText().toString());p.put("confirmed",true);d.dismiss();task(()->api("/v2/adjust",request("adjust",p)),r->open(actionId));}catch(Exception e){err.setText(e.getMessage());}}));d.show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=101||result!=RESULT_OK||actionId.isEmpty())return;task(()->{File file=new File(getCacheDir(),"capture.jpg");Bitmap b=BitmapFactory.decodeFile(file.getAbsolutePath());if(b==null)throw new IOException("Unable to read captured image");int orient=new android.media.ExifInterface(file.getAbsolutePath()).getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();if(orient==6)m.setRotate(90);else if(orient==3)m.setRotate(180);else if(orient==8)m.setRotate(270);Bitmap rotated=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),m,true);int max=Math.max(rotated.getWidth(),rotated.getHeight());Bitmap resized=max>1600?Bitmap.createScaledBitmap(rotated,rotated.getWidth()*1600/max,rotated.getHeight()*1600/max,true):rotated;ByteArrayOutputStream out=new ByteArrayOutputStream();resized.compress(Bitmap.CompressFormat.JPEG,85,out);return obj("action_id",actionId,"image_id",UUID.randomUUID().toString(),"source","camera","zoom",1,"image",Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP));},r->{pendingImage=r;actionScreen();sendImage();});}
    void sendImage(){final JSONObject p=pendingImage;if(p==null)return;task(()->api("/v2/image",p),r->{pendingImage=null;open(actionId);});}
    class Boxes extends View{Bitmap bitmap;JSONArray boxes;Paint p=new Paint(3);Boxes(Bitmap b,JSONArray boxes){super(RiceActivity.this);bitmap=b;this.boxes=boxes;}@Override protected void onDraw(Canvas c){float s=Math.min(getWidth()/(float)bitmap.getWidth(),getHeight()/(float)bitmap.getHeight()),w=bitmap.getWidth()*s,h=bitmap.getHeight()*s,x=(getWidth()-w)/2,y=(getHeight()-h)/2;p.setStyle(Paint.Style.FILL);c.drawBitmap(bitmap,null,new RectF(x,y,x+w,y+h),p);for(int i=0;i<boxes.length();i++){JSONObject r=boxes.optJSONObject(i);JSONArray b=r.optJSONArray("box");if(b==null)continue;p.setColor(TEAL);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));c.drawRect(x+(float)b.optDouble(0)*w,y+(float)b.optDouble(1)*h,x+(float)b.optDouble(2)*w,y+(float)b.optDouble(3)*h,p);}}}
}
